<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class UpdatePortfolioRequest extends FormRequest{public function authorize():bool{return true;}protected function prepareForValidation():void{$url=trim((string)$this->website_url);$this->merge(['website_url'=>$url!==''&&!preg_match('#^https?://#i',$url)?'https://'.$url:($url?:null),'upi_phone'=>filled($this->upi_phone)?preg_replace('/[\s().-]+/','',(string)$this->upi_phone):null,'ifsc'=>filled($this->ifsc)?strtoupper(trim((string)$this->ifsc)):null]);}public function rules():array{return['name'=>['required','string','max:150'],'website_url'=>['nullable','url:http,https','max:500'],'about_us'=>['nullable','string','max:5000'],'currency_code'=>['required',Rule::in(array_keys(config('portfolio.currencies')))],'status'=>['required',Rule::in(['draft','published','unpublished'])],'cover'=>['nullable','file','mimes:jpg,jpeg','mimetypes:image/jpeg','max:5120'],'remove_cover'=>['sometimes','boolean'],'image_ids'=>['array','max:'.config('portfolio.image_limit',100)],'image_ids.*'=>['integer','distinct'],'services'=>['required','array','max:30'],'services.*.id'=>['nullable','integer'],'services.*.name'=>['required','string','max:120'],'services.*.price'=>['nullable','numeric','min:0','max:9999999999.99'],'services.*.enabled'=>['required','boolean'],'show_payment_details'=>['required','boolean'],'upi_id'=>['nullable','string','max:100','regex:/^[\w.\-]{2,256}@[A-Za-z]{2,64}$/'],'upi_phone'=>['nullable','regex:/^\+?[1-9]\d{7,14}$/'],'bank_name'=>['nullable','string','max:120'],'account_holder_name'=>['nullable','string','max:120'],'account_number'=>['nullable','regex:/^\d{6,34}$/'],'account_type'=>['nullable',Rule::in(['savings','current'])],'ifsc'=>['nullable','regex:/^[A-Z]{4}0[A-Z0-9]{6}$/']];}}
